// The bridge to the Mac app's native side: `import { connectNative } from 'tilr/native'`. One
// place for what the page reaches the app through, `webkit.messageHandlers` (absent outside the
// app: a browser, an iframe build, the tests):
//
// - `connectNative()`: the bridge of paired web + native plugins (the app's `tilrNative` handler,
//   native-plugins/SDK): `describe()` the native providers, `send()` a message to one (a promise
//   of the app's acknowledgement), `on()` an event of theirs on `window`. Requests are correlated
//   by id and time out; replies arrive as 'tilr-native' events.
// - `nativeChannel()`: one of the app's own per-service handlers (`tilrAudio`, `tilrWebViews`,
//   `tilrAgent`), the core's audio / webviews / sshagent services: post a message, listen to the
//   event it answers with. Fire and forget, no correlation; null outside the app.
//
// No dependencies, no top-level work: importing it does nothing until a function is called.

/** A message handler the app registers (`webkit.messageHandlers.<name>`). */
export interface NativeHandler {
  postMessage(body: unknown): void
}

declare global {
  interface Window {
    /** WebKit's bridge to the app: present in the Mac app's WKWebView only. */
    webkit?: { messageHandlers?: Record<string, NativeHandler | undefined> }
  }
}

/** What the bridge needs of the page: its events and its WebKit handlers (`window` by default;
 *  an EventTarget with a fake `webkit` in a test). */
export type NativePage = Pick<EventTarget, 'addEventListener' | 'removeEventListener'> & { webkit?: Window['webkit'] }

/** One native provider, as `describe()` lists them. */
export interface NativeProvider {
  id: string
  version: string
  channels: string[]
  events: string[]
}

/** What `connectNative()` returns. */
export interface NativeBridge {
  /** The native providers the app has. */
  describe(): Promise<NativeProvider[]>
  /** Sends `message` to `plugin`'s `channel`; resolves when the app has dispatched it (results
   *  and state come back as the provider's events), rejects with the app's error or on timeout. */
  send(plugin: string, channel: string, message: Record<string, unknown>): Promise<{ accepted: true }>
  /** Listens to a provider's event on the page (`'tilr-audio'`); returns the undo. */
  on(event: string, listener: (detail: Record<string, unknown>) => void): () => void
  /** Rejects what is pending, removes every listener; the bridge refuses calls afterwards. */
  dispose(): void
}

/** The page by default: `globalThis.window`, undefined under Node. */
function defaultPage(): NativePage | undefined {
  return typeof window === 'undefined' ? undefined : window
}

/** The `detail` of an event, when it has one. */
function detailOf(event: Event): unknown {
  return 'detail' in event ? event.detail : undefined
}

/** A record, or null. */
function record(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null ? value as Record<string, unknown> : null
}

/**
 * The paired-plugin bridge (the app's `tilrNative` handler). Throws "Tilr native plugins are
 * unavailable" outside the app: check with `hasNative()` first for a web fallback. Dispose it
 * with the plugin: `ctx.effect(() => { const native = connectNative(); …; return () => native.dispose() })`.
 * `send()` acknowledges dispatch only; provider events carry state and results. The app's
 * control and automation services are never reachable through it.
 */
export function connectNative({ window: page = defaultPage(), timeout = 10000 }: { window?: NativePage, timeout?: number } = {}): NativeBridge {
  if (!Number.isFinite(timeout) || timeout <= 0) throw new Error('timeout must be positive')
  const handler = page?.webkit?.messageHandlers?.tilrNative
  if (!page || !handler) throw new Error('Tilr native plugins are unavailable')
  const target = page
  const pending = new Map<string, (error: Error | null, value?: unknown) => void>()
  const subscriptions = new Set<() => void>()
  // Correlation only, not authentication. Works on custom-scheme origins where
  // crypto.randomUUID may be unavailable (it requires a secure context).
  const prefix = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
  let sequence = 0
  let disposed = false
  const reply = (event: Event) => {
    const detail = record(detailOf(event))
    const finish = typeof detail?.id === 'string' ? pending.get(detail.id) : undefined
    if (detail && finish) finish(detail.error ? new Error(String(detail.error)) : null, detail.result)
  }
  target.addEventListener('tilr-native', reply)
  function request<T>(body: Record<string, unknown>): Promise<T> {
    if (disposed) return Promise.reject(new Error('native bridge disposed'))
    const id = `${prefix}:${++sequence}`
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => finish(new Error('native bridge timed out')), timeout)
      function finish(error: Error | null, value?: unknown) {
        if (!pending.delete(id)) return
        clearTimeout(timer)
        if (error) reject(error); else resolve(value as T)
      }
      pending.set(id, finish)
      try { handler?.postMessage({ ...body, id }) } catch (error) { finish(error instanceof Error ? error : new Error(String(error))) }
    })
  }
  return {
    describe: () => request<NativeProvider[]>({ op: 'describe' }),
    send: (plugin, channel, message) => request<{ accepted: true }>({ op: 'send', plugin, channel, message }),
    on(event, listener) {
      if (disposed) throw new Error('native bridge disposed')
      const receive = (e: Event) => listener(record(detailOf(e)) ?? {})
      target.addEventListener(event, receive)
      const off = () => { target.removeEventListener(event, receive); subscriptions.delete(off) }
      subscriptions.add(off)
      return off
    },
    dispose() {
      disposed = true
      target.removeEventListener('tilr-native', reply)
      for (const off of [...subscriptions]) off()
      for (const finish of [...pending.values()]) finish(new Error('native bridge disposed'))
    },
  }
}

/** True in the app, where `connectNative()` works. */
export function hasNative(page: NativePage | undefined = defaultPage()): boolean {
  return !!page?.webkit?.messageHandlers?.tilrNative
}

/** One of the app's per-service channels: what `nativeChannel()` returns. */
export interface NativeChannel<E> {
  /** Posts `body` to the app's handler. */
  post(body: unknown): void
  /** Listens to the channel's event on the page (its `detail`); returns the undo. */
  listen(listener: (detail: E) => void): () => void
}

/**
 * The app's handler `handler` (`'tilrAudio'`) and the event it answers with (`'tilr-audio'`), or
 * null when the page has no such handler (not in the app, or an app without it). Looked up now:
 * call it where the backend is chosen (a service's constructor).
 */
export function nativeChannel<E = unknown>(handler: string, event: string, page: NativePage | undefined = defaultPage()): NativeChannel<E> | null {
  const native = page?.webkit?.messageHandlers?.[handler]
  if (!page || !native) return null
  const target = page
  return {
    post: body => native.postMessage(body),
    listen(listener) {
      const receive = (e: Event) => listener(detailOf(e) as E)
      target.addEventListener(event, receive)
      return () => target.removeEventListener(event, receive)
    },
  }
}
